-- EVT hook file for soccer_formation_menu (VRFW_Host handlers, docs/framework/lua-hosts.md). Graft passive_config (util_pc_formation.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- «Configuración de pasivas» of the mod Utilities, formation screen part (soccer_formation_menu): in a mode a mod
-- declares without player passives (Utilities' [[off_mode]], CMND_UTIL_PC_OFF) the team has no passive, so its
-- «Bonificaciones de equipo» are hidden: the guide layer mainmenu01_18_team_parameter_button_guide stays invisible and
-- the team parameter menu (soccer_parameter_menu) does not open. Outside such a mode nothing changes.
-- Hook file (graft [[hooks]]): the screen has no VR-Framework host, so PostStep and OpenAndWaitTeamSkillParameterMenu
-- are wrapped directly, once per VM. State lives in UTIL_PCF.
do
  UTIL_PCF = UTIL_PCF or {}
  UTIL_PCF.CMD_OFF = 3328230312            -- CMND_UTIL_PC_OFF
  UTIL_PCF.GUIDE = 3159119257              -- mainmenu01_18_team_parameter_button_guide («Bonific. de equipo»)
  UTIL_PCF.MENU = 2049316981               -- soccer_formation_menu
  UTIL_PCF.OFF_EVERY = 30                  -- frames between two questions to the plugin
  UTIL_PCF.wrapped = UTIL_PCF.wrapped or {}

  function UTIL_PCF.OffNow()
    local ok, off = pcall(funcLuaCommand, UTIL_PCF.CMD_OFF)
    UTIL_PCF.off = ok and off == true
    UTIL_PCF.offAt = 0
    return UTIL_PCF.off
  end

  function UTIL_PCF.HideGuide()
    if funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER?]], UTIL_PCF.GUIDE) == true
        and funcLuaMenuCommand(2640875187 --[[CMND_IS_OPEN_LAYER]], UTIL_PCF.GUIDE, 0) == true then
      funcLuaMenuCommand(711242136 --[[CMND_SET_LAYER_VISIBLE]], UTIL_PCF.GUIDE, 0, false, UTIL_PCF.MENU)
    end
  end

  function UTIL_PCF.Wrap(name, make, create)
    local cur = _ENV[name]
    if UTIL_PCF.wrapped[name] == cur and cur ~= nil then
      return
    end
    if cur == nil and not create then
      return
    end
    local w = make(cur)
    _ENV[name] = w
    UTIL_PCF.wrapped[name] = w
  end

  UTIL_PCF.Wrap("PostStep", function(prev)
    return function(...)
      local r = table.pack(true)
      if prev then
        r = table.pack(prev(...))
      end
      UTIL_PCF.offAt = (UTIL_PCF.offAt or UTIL_PCF.OFF_EVERY) + 1
      if UTIL_PCF.offAt >= UTIL_PCF.OFF_EVERY then
        UTIL_PCF.OffNow()
      end
      if UTIL_PCF.off then
        pcall(UTIL_PCF.HideGuide)
      end
      if prev then
        return table.unpack(r, 1, r.n)
      end
    end
  end, true)

  UTIL_PCF.Wrap("OpenAndWaitTeamSkillParameterMenu", function(prev)
    return function(...)
      if UTIL_PCF.OffNow() then
        return
      end
      return prev(...)
    end
  end)
end
